def refs():
    return [{**s, "subject": "science", "locator": "太陽能量來源、食物鏈與食物網、營養階層、能量塔及能量遞減", "observedPattern": "公開公立學校生物資料常用食物鏈、食物網和能量塔圖表判讀生產者、消費者與能量流轉；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bd-iv-1-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供食物鏈、食物網、營養階層與能量塔的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開公立學校生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "在草→蝗蟲→青蛙→蛇的食物鏈中，箭頭最合理表示什麼方向？", {"A": "被食者提供的能量與物質流向捕食者", "B": "捕食者把能量全部送回草", "C": "箭頭只表示生物的移動方向", "D": "箭頭表示水分循環而非攝食"}, "A", "食物鏈箭頭通常由被食者指向捕食者，表示攝食時能量與物質的傳遞方向，選 A。", "先問箭頭兩端誰吃誰，再將攝食關係連到能量流動。", ["草是被蝗蟲取食的生物。", "蝗蟲的有機物和能量可傳給青蛙。", "箭頭沿被吃者指向吃者。", "它不是單純的移動或水循環符號。", "所以選 A。"], "easy"),
    make(2, "在同一食物鏈中，最接近太陽能最初轉換位置的生物通常是？", {"A": "生產者", "B": "最高階捕食者", "C": "分解者", "D": "所有消費者都相同"}, "A", "植物或藻類等生產者利用光合作用把光能轉成化學能，是能量進入食物鏈的主要入口，選 A。", "沿食物鏈從能量來源往後找第一個能自行製造有機物的營養階層。", ["生態系能量主要來自太陽。", "生產者能利用光能合成有機物。", "草食和肉食動物需透過攝食取得能量。", "因此最初轉換位置是生產者。", "所以選 A。"], "easy"),
    make(3, "若食物鏈為向日葵→兔→蛇→鷹，哪個生物是初級消費者？", {"A": "兔", "B": "向日葵", "C": "蛇", "D": "鷹"}, "A", "初級消費者直接取食生產者；兔直接吃向日葵，因此是初級消費者，選 A。", "從食物鏈找直接吃生產者的第一個動物。", ["辨認向日葵是生產者。", "找直接以向日葵為食者。", "兔位於生產者後一階。", "蛇與鷹分別在更高營養階層。", "所以選 A。"], "easy"),
    make(4, "能量塔通常由底層向上逐漸變窄，主要原因是？", {"A": "各營養階層傳給下一階層的能量有限，部分以熱散失", "B": "高階生物一定比低階生物體型小", "C": "太陽能會從高階流回植物", "D": "能量塔只表示生物數量而與能量無關"}, "A", "生物利用食物能量時有部分散失為熱，下一階層可取得的能量通常較少，所以能量塔向上遞減，選 A。", "把塔的寬度解讀為能量量，再追蹤每次傳遞的損失。", ["底層通常代表生產者總能量。", "生物維持生命活動會消耗能量。", "部分能量以熱散失，不能全部傳遞。", "高階營養階層可用能量因而通常較少。", "所以選 A。"], "medium"),
    make(5, "若食物網中的一種植物大量減少，最先直接受到影響的通常是哪類生物？", {"A": "直接取食該植物的初級消費者", "B": "與植物完全沒有攝食關係的生物必定全部增加", "C": "太陽本身", "D": "所有分解者立刻消失"}, "A", "直接依賴該植物取得食物的初級消費者會先面臨食物減少；後續影響仍要看食物網替代路徑，選 A。", "沿著受影響植物的食物連線找直接依賴者，再避免把局部影響擴大成必然全網結果。", ["找出植物在食物網中的位置。", "辨認直接以它為食的消費者。", "植物減少會先降低這些生物的食物供給。", "其他生物的變化需依其餘連線判斷。", "因此選 A。"], "medium"),
    make(6, "下列何者最能表示能量在生態系中的一般方向？", {"A": "太陽→生產者→各級消費者，沿途部分散失為熱", "B": "最高階消費者→太陽→生產者", "C": "分解者把熱能全部送回太陽", "D": "能量在生態系內無限循環而沒有散失"}, "A", "太陽提供主要能量，生產者固定後經食物鏈傳給消費者，傳遞過程有熱散失，選 A。", "先畫能量來源，再依攝食方向向上追蹤並標註散失。", ["辨認太陽是主要外部能量來源。", "生產者先把光能轉成化學能。", "消費者透過攝食取得部分能量。", "每階層代謝都會有熱散失。", "所以選 A。"], "easy"),
    make(7, "食物鏈相同時，若某高階捕食者獲得的能量較少，哪個推論最合理？", {"A": "它位於較高營養階層，前面多次傳遞已造成能量損失", "B": "它一定完全不需要呼吸作用", "C": "低階生物一定沒有能量", "D": "能量會因捕食者變大而自動增加"}, "A", "能量由低階向高階傳遞時逐級減少，高階捕食者可取得的總能量通常較少，選 A。", "用營養階層數目判斷傳遞次數，不把個體大小直接當成能量來源。", ["定位捕食者在食物鏈中的階層。", "數它之前經過的攝食轉移。", "每次轉移都有代謝與熱散失。", "因此可到達的能量逐步減少。", "所以選 A。"], "medium"),
    make(8, "同一生態系有多條食物鏈交織，形成食物網的好處之一是？", {"A": "某一食物來源減少時，部分消費者可能仍有其他攝食路徑", "B": "食物網能讓能量無損傳遞", "C": "食物網會消除所有競爭", "D": "食物網中不再有生產者"}, "A", "食物網提供多條連結，某一來源減少時部分消費者可能改取其他食物；但能量仍會在傳遞中散失，選 A。", "比較單一食物鏈與多連線食物網的替代路徑和限制。", ["辨認食物網包含多條相互交織的食物鏈。", "找出一個消費者的其他食物連線。", "某一來源減少時，替代路徑可降低衝擊。", "這不代表沒有能量散失或競爭。", "所以選 A。"], "hard"),
    make(9, "若將能量塔誤當成生物數量塔，最可能犯的錯誤是？", {"A": "把塔的寬度直接解讀成個體數，忽略題目其實呈現能量", "B": "認為太陽是最高階消費者", "C": "把所有植物列為分解者", "D": "認為箭頭一定表示水流"}, "A", "不同金字塔可表示能量、生物量或數量；題目若明示能量塔，就不能把寬度直接當個體數，選 A。", "先讀圖例和縱軸標示，再判斷每層寬度的物理意義。", ["確認圖表標題或單位。", "能量塔的寬度代表該營養階層能量量。", "數量塔則需有個體數資料。", "沒有圖例就不能任意替換解釋。", "所以選 A。"], "hard"),
    make(10, "關於生態系能量流轉，哪個敘述最嚴謹？", {"A": "能量主要單向流動並逐級散失，物質循環與能量流動不能混為一談", "B": "能量和碳元素都以完全相同方式無限循環", "C": "分解者會把熱重新變成太陽能", "D": "只要有生產者，所有能量就能被消費者利用"}, "A", "能量由太陽進入後沿營養階層傳遞並逐步散失；元素可循環，但能量流動不能與物質循環混為一談，選 A。", "先分辨能量和物質兩個概念，再各自追蹤來源、去向與是否循環。", ["能量從太陽進入生態系。", "經生產者和消費者傳遞時部分轉成熱。", "物質元素可在生物與環境間循環。", "兩種流動的規則不同。", "因此選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    old = {o["id"]: o["text"] for o in q["options"]}
    old["A"], old[target] = old[target], old["A"]
    q["options"] = [{"id": k, "text": old[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A", f"選 {target}")
    q["solutionStrategy"] = q["solutionStrategy"].replace("選 A", f"選 {target}")
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("所以選 A", f"所以選 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
